use pulldown_cmark::Options;
fn render(input: &str, opts: Options) -> String {
    let parser = pulldown_cmark::Parser::new_ext(input, opts);
    let mut out = String::new();
    pulldown_cmark::html::push_html(&mut out, parser);
    out
}
fn main() {
    let subscript_only = Options::ENABLE_SUBSCRIPT;
    let both = Options::ENABLE_SUBSCRIPT | Options::ENABLE_STRIKETHROUGH;
    let strikethrough_only = Options::ENABLE_STRIKETHROUGH;

    println!("== subscript only ==");
    for input in [
        "~~This ~is~~ stricken.~",
        "a ~[x](https://x)~",
        "b ~~[x](https://x)~~",
        "d ~~x ~[x](https://x)~ x~~",
    ] {
        println!("{:?}\n -> {}", input, render(input, subscript_only));
    }

    println!("== both ==");
    for input in ["~~stricken~~", "~sub~", "H~2~O"] {
        println!("{:?}\n -> {}", input, render(input, both));
    }

    println!("== strikethrough only ==");
    for input in ["~~This is *stricken out*~~", "~This is stricken out~", "This~is~nothing", "Here I strike out an exclamation point~~!~~."] {
        println!("{:?}\n -> {}", input, render(input, strikethrough_only));
    }
}
